import re, html
raw = open('top10.html', encoding='utf-8').read()
start = raw.find('Top 10 Most Challenged Books of 2020')
end = raw.find('Top 10 Most Challenged Books of 2014')
seg = raw[start:end]
t = re.sub(r'<[^>]+>','\n',seg); t=html.unescape(t)
lines=[l.strip() for l in t.split('\n') if l.strip()]
# split by year headings
years={}
cur=None
for l in lines:
    m=re.match(r'Top \d+ Most Challenged Books of (\d{4})', l)
    if m:
        cur=int(m.group(1)); years[cur]=[]
        continue
    if cur and (l.startswith('Reasons:') or l.startswith('Reason:') or l.startswith('Download') or 'infographic' in l or l.startswith('The ALA Office') or l.startswith('Out of ') or l.startswith('Number of')):
        continue
    if cur and re.search(r'\bby\b|written|^The Holy Bible|^Melissa|^Drama|^Harry Potter|^Captain Underpants|^Skippyjon Jones|^Little Bill|^Stamp', l) and not l.startswith('('):
        years[cur].append(l)
for y in sorted(years):
    print('==',y)
    for x in years[y]: print('  ',x)
EOF
